import { useEffect, useState } from 'react';

export type GreetingProps = {
  visible: boolean;
  name: string;
};

export function Greeting({ visible, name }: GreetingProps) {
  const [greeting, setGreeting] = useState('');

  useEffect(() => {
    setGreeting(`Hello, ${name}`);
  }, [name]);

  if (!visible) {
    return null;
  }

  return <p>{greeting}</p>;
}
